import {createBossEmissionMaterials,BOSS_EMISSION_PROFILES,BOSS_EMISSION_SPEC} from './boss-emission-materials.js';
import {bindSceneryEmission} from './scenery-emission-bridge.js';
import {createSceneryEmissionMaterials,SCENERY_EMISSION_SPEC,HEDGEHOG_EMISSION_COLORS} from './approved-scenery-materials.js';
import {CAMPAIGN_CAVE_ART} from './campaign-cave-data.js';
import {DUNGEON_MATERIALS} from './dungeon-volumes.js';
import {paintWallPyreEmission} from './cave-wall-pyres-art.js';
// One scene-owned buffer. Native painters supply their exact pose, clips and wall
// alpha. Only selected crystal/cap/fire pixels survive the late darkness pass.
export function createApprovedSceneryEmission(world,scene,{makeCanvas,canonicalAtlas=null}={}){
 let dead=false,materials=null,layer=null,g=null,sources=[],draws=0,occlusions=0,additions=0,pyres=0;
 const bossMaterials=createBossEmissionMaterials(makeCanvas),bossKeys=new Set();let bossSources=[];
 const halos=new Map();let resolveReady;const ready=new Promise(resolve=>{resolveReady=resolve;});
 const makeMaterials=image=>{if(!dead)materials=createSceneryEmissionMaterials({makeCanvas,canonicalAtlas:image,materialRamps:DUNGEON_MATERIALS});resolveReady();};
 if(canonicalAtlas||scene.biome===0&&scene.images.get('hedgehog-atlas'))makeMaterials(canonicalAtlas||scene.images.get('hedgehog-atlas'));
 else if(typeof Image!=='undefined'){const im=new Image();im.onload=()=>{im.onload=im.onerror=null;makeMaterials(im);};im.onerror=()=>{im.onload=im.onerror=null;makeMaterials(null);};im.src=CAMPAIGN_CAVE_ART[0].assets['hedgehog-atlas'];}else makeMaterials(null);
 function context(c){if(!layer){layer=makeCanvas(c.canvas.width,c.canvas.height);g=layer.getContext('2d');}const t=c.getTransform();g.setTransform(t.a,t.b,t.c,t.d,t.e,t.f);g.globalAlpha=1;g.globalCompositeOperation='source-over';return g;}
 function inView(c,x,y,r=120){const t=c.getTransform(),px=t.a*x+t.c*y+t.e,py=t.b*x+t.d*y+t.f,margin=r*Math.max(Math.abs(t.a),Math.abs(t.d));return px>-margin&&py>-margin&&px<c.canvas.width+margin&&py<c.canvas.height+margin;}
 function source(x,y,color,radius,alpha,kind,grid=null){if(kind==='wall-pyre'?pyres++>=8:additions++>=SCENERY_EMISSION_SPEC.maxSources)return;const gy=(y-57.5)/16,gx=(x-50-2*gy)/22;sources.push({x,y,color,radius,alpha,kind,grid:grid||{x:gx,y:gy}});}
 function bossVisible(p){if(!scene.room.explored)return true;const y=Math.round((p.y-57.5)/16),x=Math.round((p.x-50-2*((p.y-57.5)/16))/22);return !!scene.room.visible?.[y*scene.room.cols+x];}
 function bossSource(data){if(!bossVisible(data.anchor)||!BOSS_EMISSION_PROFILES[data.index]||!(data.alpha>0))return;const {x,y}=data.anchor,key=[data.index,x.toFixed(2),y.toFixed(2)].join(':');if(bossKeys.has(key)||bossSources.length>=BOSS_EMISSION_SPEC.maxSources)return;bossKeys.add(key);const gy=(y-57.5)/16;bossSources.push({index:data.index,x,y,alpha:Math.min(1,data.alpha),color:BOSS_EMISSION_PROFILES[data.index].color,grid:{x:(x-50-2*gy)/22,y:gy}});}
 function capture(c,kind,data){if(dead)return;
  if(kind==='boss-source'){if(inView(c,data.anchor.x,data.anchor.y))bossSource(data);return;}
  if(kind==='boss-atlas'){if(!(data.alpha>0)||!bossVisible(data.anchor)||!inView(c,data.anchor.x,data.anchor.y))return;bossSource(data);const v=bossMaterials.atlas(data.image,data.sourceRect);if(!v?.pixels)return;const q=context(c);q.save();q.globalAlpha=data.alpha;q.drawImage(v.canvas,...data.rect);q.restore();draws++;return;}
  if(kind==='boss-raster'){const v=bossMaterials.raster(data.image);if(!v?.pixels)return;const q=context(c);q.save();q.globalAlpha=data.alpha;q.drawImage(v.canvas,...data.rect);q.restore();draws++;return;}
  if(kind==='boss-mesh'){if(!(data.alpha>0)||!bossVisible(data.anchor)||!inView(c,data.anchor.x,data.anchor.y))return;bossSource(data);const v=bossMaterials.mesh(data.faces,data.index,data.cache);if(!v)return;const q=context(c);q.save();q.transform(...data.matrix);q.globalAlpha=data.alpha;
   if(!data.cache&&draws){q.globalCompositeOperation='destination-out';q.beginPath();for(const f of data.faces){f.points.forEach(([a,b,z],i)=>i?q.lineTo(a+b/11,b*8/11-z):q.moveTo(a+b/11,b*8/11-z));q.closePath();}q.fillStyle='#000000';q.fill();}
   q.globalCompositeOperation='source-over';q.drawImage(v.canvas,v.x,v.y,v.w,v.h);q.restore();bossSource(data);draws++;return;}

  if(kind==='chest-treasure'){if(data.paint(context(c)))draws++;return;}
  if(kind==='occluder'){if(!draws)return;const q=context(c);q.save();q.globalCompositeOperation='destination-out';q.drawImage(...data);q.restore();occlusions++;return;}
  if(kind==='hedgehog'){const{image,frame,clip,traceArch,cx,cy}=data;if(!inView(c,cx,cy))return;const m=materials?.hedgehog(image,frame,scene.biome);if(!m)return;const q=context(c);q.save();q.clip(clip,'evenodd');traceArch(q,cx,cy);q.clip();q.drawImage(m.canvas,cx-96+m.left/2,cy-130+m.top/2,m.width/2,m.height/2);q.restore();source(cx-7,cy+1,m.color,72,.30,'hedgehog-crystals');draws++;return;}
  if(kind==='legacy-hedgehog'){const{image,x,y,width,height,baseTransform,arch}=data;if(!inView(c,x,y))return;const q=context(c);q.save();if(arch){q.setTransform(baseTransform);arch(q);q.clip();q.setTransform(c.getTransform());}q.globalAlpha=.84;q.shadowColor=HEDGEHOG_EMISSION_COLORS[scene.biome];q.shadowBlur=6;q.drawImage(image,0,0,width,height);q.restore();source(x,y,HEDGEHOG_EMISSION_COLORS[scene.biome],72,.30,'hedgehog-crystals');draws++;return;}
  if(kind==='mushroom'){const{a,type,x,y,width,options}=data;if(!inView(c,x,y,40))return;const m=materials?.mushroom(a,type,options);if(!m)return;const q=context(c),s=width/100;q.drawImage(m.canvas,x-54*s,y-100*s,108*s,118*s);source(x,y,m.color,type==='mushroom'?24:31,type==='mushroom'?.13:.18,type==='mushroom'?'small-green-cap':options.variant===2?'explosive-cap':'healing-cap');draws++;return;}
  if(kind==='nucleus'){const{faces,x,y,scale}=data;if(!inView(c,x,y,40))return;const q=context(c);q.save();q.translate(x,y);q.scale(scale,scale);for(const f of faces){const cap=f.id.startsWith('nucleus-cap');q.globalCompositeOperation=cap?'source-over':'destination-out';q.globalAlpha=cap?.22+.52*parseInt(f.fill.slice(3,5),16)/255:1;q.beginPath();f.points.forEach(([a,b,z],i)=>i?q.lineTo(a+b/11,b*8/11-z):q.moveTo(a+b/11,b*8/11-z));q.closePath();q.fillStyle='#64ff58';q.fill();}q.restore();source(x,y,'#64ff58',26,.16,'small-green-nucleus-cap');draws++;return;}
  if(kind==='wall-pyre'){const{item,time,soft,player}=data,q=context(c);paintWallPyreEmission(q,item,{time,soft,player});const p=item.projected.flame;source(p.x,p.y,item.material.light||item.material.gem[0],58,.30,'wall-pyre',item.grid);draws++;}
 }
 const unbind=bindSceneryEmission(world.canvas,{capture});
 function begin(){if(dead)return;if(layer){if(layer.width!==world.canvas.width)layer.width=world.canvas.width;if(layer.height!==world.canvas.height)layer.height=world.canvas.height;g.resetTransform();g.clearRect(0,0,layer.width,layer.height);}sources=[];bossSources=[];bossKeys.clear();draws=occlusions=additions=pyres=0;}
 function halo(p,masks){if(!masks?.sourcePath)return null;const key=[p.kind,p.x,p.y,p.color,p.radius,p.alpha].join(':');let v=halos.get(key);if(v?.floor===masks.floor){halos.delete(key);halos.set(key,v);return v;}const path=masks.sourcePath(p.grid);if(v){v.canvas.width=v.canvas.height=1;halos.delete(key);}const r=p.radius,x=Math.floor(p.x-r),y=Math.floor(p.y-r*.57),w=Math.ceil(r*2)+2,h=Math.ceil(r*1.14)+2,canvas=makeCanvas(w,h),q=canvas.getContext('2d');q.translate(-x,-y);q.clip(masks.floor);q.clip(path);q.translate(p.x,p.y);q.scale(1,.57);const grad=q.createRadialGradient(0,0,0,0,0,r);grad.addColorStop(0,p.color+'c0');grad.addColorStop(.28,p.color+'64');grad.addColorStop(1,p.color+'00');q.fillStyle=grad;q.fillRect(-r,-r,r*2,r*2);v={canvas,floor:masks.floor,x,y,w,h};while(halos.size>=SCENERY_EMISSION_SPEC.maxHaloCaches){const k=halos.keys().next().value;halos.get(k).canvas.width=1;halos.delete(k);}halos.set(key,v);return v;}
 function paint(c,masks,{gain=1,lights=true,duck=1,bossMasks=masks,ambientGain=1}={}){if(dead||(!draws&&!bossSources.length)||gain<=0)return;c.save();c.globalCompositeOperation='screen';for(const p of sources){if(p.kind==='wall-pyre'&&!lights)continue;const v=halo(p,masks);if(!v)continue;c.globalAlpha=Math.min(1,p.alpha*gain*duck);c.drawImage(v.canvas,v.x,v.y,v.w,v.h);}for(const b of bossSources){for(const [kind,color,radius,alpha]of [['boss-body',scene.data.material.light||scene.data.material.gem[0],BOSS_EMISSION_SPEC.bodyRadius,.14*ambientGain],['boss-part',b.color,43,.18*gain]]){const v=halo({...b,kind,color,radius,alpha},bossMasks);if(!v)continue;c.globalAlpha=Math.min(1,alpha*b.alpha*duck);c.drawImage(v.canvas,v.x,v.y,v.w,v.h);}}c.restore();c.save();c.resetTransform();c.globalCompositeOperation='screen';c.globalAlpha=Math.min(1,gain*duck);if(layer)c.drawImage(layer,0,0);c.restore();}
 function paintBossNight(c,viewport,hole,masks,{strength=1}={}){if(dead||strength<=0)return;for(const b of bossSources){c.save();c.translate(-viewport.x+4,-viewport.y+4);if(masks?.sourcePath)c.clip(masks.sourcePath(b.grid,true));c.translate(viewport.x-4,viewport.y-4);hole(b.x-viewport.x+4,b.y-viewport.y-22,BOSS_EMISSION_SPEC.bodyRadius,BOSS_EMISSION_SPEC.bodyPower*b.alpha*Math.min(1.25,strength));c.restore();}}
 return {ready,begin,capture,paint,paintBossNight,get debugCanvas(){return layer;},status:()=>({sources:sources.map(p=>({...p})),draws,occlusions,bossSources:bossSources.map(p=>({...p})),bossMaterials:bossMaterials.status(),haloCaches:halos.size,materials:materials?.status()||null,canvasBytes:bossMaterials.status().canvasBytes+(layer?layer.width*layer.height*4:0)+[...halos.values()].reduce((n,v)=>n+v.canvas.width*v.canvas.height*4,0)+(materials?.status().cachedRasterBytes||0)+(materials?.status().templateBytes||0)}),dispose(){if(dead)return;dead=true;resolveReady();unbind();bossMaterials.dispose();bossSources=[];bossKeys.clear();materials?.dispose();if(layer)layer.width=layer.height=1;for(const v of halos.values())v.canvas.width=v.canvas.height=1;halos.clear();sources=[];}};
}
